//! Pure-Rust port of mapbox earcut.hpp (C++ port of mapbox/earcut).
//!
//! The original C++ stores `Node` objects in a vector and links them with raw
//! pointers.  Here we keep the nodes in an arena (`Vec<Node>`) and use indices
//! into that arena exactly like the pointers in the original; `NIL` plays the
//! role of `nullptr`.  Every algorithmic decision is reproduced line for line.

pub const NIL: usize = usize::MAX;

#[derive(Clone)]
struct Node {
    i: u32, // vertex index in the resulting indices array
    x: f64,
    y: f64,

    prev: usize,
    next: usize,

    z: i32, // z-order curve value
    prev_z: usize,
    next_z: usize,

    steiner: bool,
}

impl Node {
    fn new(i: u32, x: f64, y: f64) -> Self {
        Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        }
    }
}

pub struct Earcut {
    pub indices: Vec<u32>,
    nodes: Vec<Node>,
    vertices: u32,

    min_x: f64,
    min_y: f64,
    inv_size: f64,
    hashing: bool,
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            indices: Vec::new(),
            nodes: Vec::new(),
            vertices: 0,
            min_x: 0.0,
            min_y: 0.0,
            inv_size: 0.0,
            hashing: false,
        }
    }

    /// Triangulate a polygon given as a list of rings (outer ring first, then holes).
    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        // reset
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        let mut threshold: i64 = 80;
        let mut len: usize = 0;

        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i64;
            len += points[i].len();
            i += 1;
        }

        // estimate size of nodes and indices
        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NIL
            || self.nodes[outer_node].prev == self.nodes[outer_node].next
        {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later; calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.min_y = self.nodes[outer_node].y;
            let mut max_x = self.nodes[outer_node].x;
            let mut max_y = self.nodes[outer_node].y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                self.min_x = self.min_x.min(x);
                self.min_y = self.min_y.min(y);
                max_x = max_x.max(x);
                max_y = max_y.max(y);
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }
            self.inv_size = (max_x - self.min_x).max(max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.5 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);

        self.nodes.clear();
    }

    // Creates a circular doubly linked list from polygon points in the specified winding order.
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let mut last = NIL;

        if clockwise == (signed_area(points) > 0.0) {
            for p in points {
                let v = self.vertices;
                self.vertices += 1;
                last = self.insert_node(v, p[0], p[1], last);
            }
        } else {
            let mut i = points.len() as i64 - 1;
            while i >= 0 {
                let p = points[i as usize];
                let v = self.vertices;
                self.vertices += 1;
                last = self.insert_node(v, p[0], p[1], last);
                i -= 1;
            }
        }

        if last != NIL && self.equals(last, self.nodes[last].next) {
            self.remove_node(last);
            last = self.nodes[last].next;
        }

        last
    }

    // eliminate colinear or duplicate points
    fn filter_points(&mut self, start: usize, mut end: usize) -> usize {
        if start == NIL {
            return start;
        }
        if end == NIL {
            end = start;
        }

        let mut p = start;
        loop {
            let mut again = false;

            let pn = self.nodes[p].next;
            let pp = self.nodes[p].prev;
            if !self.nodes[p].steiner
                && (self.equals(p, pn) || self.area(pp, p, pn) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    fn earcut_linked(&mut self, mut ear: usize, pass: i32) {
        if ear == NIL {
            return;
        }

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let ear_found = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if ear_found {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                // try filtering points and slicing again
                if pass == 0 {
                    let e = self.filter_points(ear, NIL);
                    self.earcut_linked(e, 1);
                // if this didn't work, try curing all small self-intersections locally
                } else if pass == 1 {
                    let e = self.filter_points(ear, NIL);
                    let e = self.cure_local_intersections(e);
                    self.earcut_linked(e, 2);
                // as a last resort, try splitting the remaining polygon into two
                } else if pass == 2 {
                    self.split_ears(ear);
                }

                break;
            }
        }
    }

    // check whether a polygon node forms a valid ear with adjacent nodes
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        let mut p = self.nodes[self.nodes[ear].next].next;

        while p != self.nodes[ear].prev {
            if point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx.min(cx));
        let min_ty = ay.min(by.min(cy));
        let max_tx = ax.max(bx.max(cx));
        let max_ty = ay.max(by.max(cy));

        // z-order range for the current triangle bbox;
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;

        while p != NIL && self.nodes[p].z <= max_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;

        while p != NIL && self.nodes[p].z >= min_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    // go through all polygon nodes and cure small local self-intersections
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut start = start;
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;

            // a self-intersection where edge (v1,v2) intersects (v3,v4)
            if !self.equals(a, b)
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                let pn = self.nodes[p].next;
                self.remove_node(p);
                self.remove_node(pn);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    // try splitting polygon into two and triangulate them independently
    fn split_ears(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    a = self.filter_points(a, self.nodes[a].next);
                    let c = self.filter_points(c, self.nodes[c].next);

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    // link every hole into the outer loop, producing a single-ring polygon without holes
    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], mut outer_node: usize) -> usize {
        let mut queue: Vec<usize> = Vec::new();
        for i in 1..points.len() {
            let list = self.linked_list(&points[i], false);
            if list != NIL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }
        queue.sort_by(|&a, &b| {
            self.nodes[a]
                .x
                .partial_cmp(&self.nodes[b].x)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        // process holes from left to right
        for &q in &queue {
            outer_node = self.eliminate_hole(q, outer_node);
        }

        outer_node
    }

    // find a bridge between vertices that connects hole with an outer ring and link it
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        self.filter_points(bridge_reverse, self.nodes[bridge_reverse].next);

        self.filter_points(bridge, self.nodes[bridge].next)
    }

    // David Eberly's algorithm for finding a bridge between hole and outer polygon
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost point to the left;
        // segment's endpoint with lesser x will be potential connection point
        loop {
            let pn = self.nodes[p].next;
            if hy <= self.nodes[p].y
                && hy >= self.nodes[pn].y
                && self.nodes[pn].y != self.nodes[p].y
            {
                let x = self.nodes[p].x
                    + (hy - self.nodes[p].y)
                        * (self.nodes[pn].x - self.nodes[p].x)
                        / (self.nodes[pn].y - self.nodes[p].y);
                if x <= hx && x > qx {
                    qx = x;
                    m = if self.nodes[p].x < self.nodes[pn].x { p } else { pn };
                    if x == hx {
                        return m; // hole touches outer segment; pick lower endpoint
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // look for points inside the triangle of hole point, segment intersection and endpoint;
        // if there are no points found, we have a valid connection;
        // otherwise choose the point of the minimum angle with the ray as connection point
        let stop = m;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;
        let mut tan_min = f64::INFINITY;

        p = m;

        loop {
            if hx >= self.nodes[p].x
                && self.nodes[p].x >= mx
                && hx != self.nodes[p].x
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
            {
                let tan_cur = (hy - self.nodes[p].y).abs() / (hx - self.nodes[p].x); // tangential

                if self.locally_inside(p, hole)
                    && (tan_cur < tan_min
                        || (tan_cur == tan_min
                            && (self.nodes[p].x > self.nodes[m].x
                                || (self.nodes[p].x == self.nodes[m].x
                                    && self.sector_contains_sector(m, p)))))
                {
                    m = p;
                    tan_min = tan_cur;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }

    // whether sector in vertex m contains sector in vertex p in the same coordinates
    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.nodes[m].prev, m, self.nodes[p].prev) < 0.0
            && self.area(self.nodes[p].next, m, self.nodes[m].next) < 0.0
    }

    // interlink polygon nodes in z-order
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            let z = self.z_order(self.nodes[p].x, self.nodes[p].y);
            self.nodes[p].z = z;
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let ppz = self.nodes[p].prev_z;
        self.nodes[ppz].next_z = NIL;
        self.nodes[p].prev_z = NIL;

        self.sort_linked(p);
    }

    // Simon Tatham's linked list merge sort algorithm
    // http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
    fn sort_linked(&mut self, mut list: usize) -> usize {
        let mut in_size = 1usize;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0usize;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NIL {
                        break;
                    }
                }

                let mut q_size = in_size;

                // if there are more merges, merge two lists
                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NIL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    // z-order of a point given coords and size of the data bounding box
    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }

    // find the leftmost node of a polygon ring
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        leftmost
    }

    // check if a diagonal between two polygon nodes is valid (lies in polygon interior)
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        self.nodes[self.nodes[a].next].i != self.nodes[b].i
            && self.nodes[self.nodes[a].prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b) // locally visible
                && (self.area(self.nodes[a].prev, a, self.nodes[b].prev) != 0.0
                    || self.area(a, self.nodes[b].prev, b) != 0.0)) // does not create opposite-facing sectors
                || (self.equals(a, b)
                    && self.area(self.nodes[a].prev, a, self.nodes[a].next) > 0.0
                    && self.area(self.nodes[b].prev, b, self.nodes[b].next) > 0.0)) // special zero-length case
    }

    // signed area of a triangle
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    // check if two points are equal
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    // check if two segments intersect
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));

        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true; // p1, q1 and p2 are collinear and p2 lies on p1q1
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true; // p1, q1 and q2 are collinear and q2 lies on p1q1
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true; // p2, q2 and p1 are collinear and p1 lies on p2q2
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true; // p2, q2 and q1 are collinear and q1 lies on p2q2
        }

        false
    }

    // for collinear points p, q, r, check if point q lies on segment pr
    fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        self.nodes[q].x <= self.nodes[p].x.max(self.nodes[r].x)
            && self.nodes[q].x >= self.nodes[p].x.min(self.nodes[r].x)
            && self.nodes[q].y <= self.nodes[p].y.max(self.nodes[r].y)
            && self.nodes[q].y >= self.nodes[p].y.min(self.nodes[r].y)
    }

    // check if a polygon diagonal intersects any polygon segments
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        false
    }

    // check if a polygon diagonal is locally inside the polygon
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        if self.area(self.nodes[a].prev, a, self.nodes[a].next) < 0.0 {
            self.area(a, b, self.nodes[a].next) >= 0.0
                && self.area(a, self.nodes[a].prev, b) >= 0.0
        } else {
            self.area(a, b, self.nodes[a].prev) < 0.0
                || self.area(a, self.nodes[a].next, b) < 0.0
        }
    }

    // check if the middle point of a polygon diagonal is inside the polygon
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            if ((self.nodes[p].y > py) != (self.nodes[pn].y > py))
                && self.nodes[pn].y != self.nodes[p].y
                && (px
                    < (self.nodes[pn].x - self.nodes[p].x) * (py - self.nodes[p].y)
                        / (self.nodes[pn].y - self.nodes[p].y)
                        + self.nodes[p].x)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        inside
    }

    // link two polygon vertices with a bridge; if the vertices belong to the same ring, it splits
    // polygon into two; if one belongs to the outer ring and another to a hole, it merges it into a
    // single ring
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let a2 = self.create_node(ai, ax, ay);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let b2 = self.create_node(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    // create a node and optionally link it with previous one (in a circular doubly linked list)
    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: usize) -> usize {
        let p = self.create_node(i, x, y);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            self.nodes[p].next = self.nodes[last].next;
            self.nodes[p].prev = last;
            let ln = self.nodes[last].next;
            self.nodes[ln].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    fn create_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node::new(i, x, y));
        self.nodes.len() - 1
    }

    fn remove_node(&mut self, p: usize) {
        let (pp, pn, ppz, pnz) = {
            let n = &self.nodes[p];
            (n.prev, n.next, n.prev_z, n.next_z)
        };
        self.nodes[pn].prev = pp;
        self.nodes[pp].next = pn;

        if ppz != NIL {
            self.nodes[ppz].next_z = pnz;
        }
        if pnz != NIL {
            self.nodes[pnz].prev_z = ppz;
        }
    }
}

// check if a point lies within a convex triangle
fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) >= (ax - px) * (cy - py)
        && (ax - px) * (by - py) >= (bx - px) * (ay - py)
        && (bx - px) * (cy - py) >= (cx - px) * (by - py)
}

fn sign(val: f64) -> i32 {
    ((0.0 < val) as i32) - ((val < 0.0) as i32)
}

fn signed_area(points: &[[f64; 2]]) -> f64 {
    let len = points.len();
    let mut sum = 0.0;
    let mut j = len.wrapping_sub(1);
    for i in 0..len {
        let p1 = points[i];
        let p2 = points[j];
        sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
        j = i;
    }
    sum
}

