mod earcut;

use earcut::Earcut;

/// Parse like C `atoi`: skip leading whitespace, optional sign, digits;
/// anything else yields 0.
fn atoi(s: &str) -> i64 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }
    let mut sign = 1i64;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val * 10 + (bytes[i] - b'0') as i64;
        i += 1;
    }
    sign * val
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: i64 = if args.len() > 1 { atoi(&args[1]) } else { 11 };

    // build the "gear" polygon with 2n vertices:
    // outer point on the unit circle, inner point at radius 0.7, interleaved
    let mut ring: Vec<[f64; 2]> = Vec::new();
    for i in 0..n {
        let a = 2.0 * std::f64::consts::PI * i as f64 / n as f64;
        ring.push([a.cos(), a.sin()]);
        let b = 2.0 * std::f64::consts::PI * (i as f64 + 0.5) / n as f64;
        ring.push([0.7 * b.cos(), 0.7 * b.sin()]);
    }

    let polygon = vec![ring];
    let mut ec = Earcut::new();
    ec.run(&polygon);

    let mut out = String::new();
    for idx in &ec.indices {
        out.push_str(&idx.to_string());
        out.push(' ');
    }
    print!("{}", out);
}

