// Pure Rust port of mapbox earcut.hpp (C++ port of mapbox/earcut).
// Reproduces the reference algorithm exactly, including its floating point
// operation order, so emitted triangle indices match the C++ implementation.

const NULL: usize = usize::MAX;

struct Node {
    i: u32,
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    // z-order curve value
    z: i32,
    // previous/next nodes in z-order
    prev_z: usize,
    next_z: usize,
    // indicates whether this is a steiner point
    steiner: bool,
}

pub struct Earcut {
    pub indices: Vec<u32>,
    vertices: u32,
    nodes: Vec<Node>,
    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

pub fn earcut(points: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut e = Earcut {
        indices: Vec::new(),
        vertices: 0,
        nodes: Vec::new(),
        hashing: false,
        min_x: 0.0,
        max_x: 0.0,
        min_y: 0.0,
        max_y: 0.0,
        inv_size: 0.0,
    };
    e.run(points);
    e.indices
}

impl Earcut {
    fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        if points.is_empty() {
            return;
        }

        let mut threshold: i64 = 80;
        let mut len: usize = 0;

        let mut i = 0usize;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i64;
            len += points[i].len();
            i += 1;
        }

        let outer = self.linked_list(&points[0], true);
        let mut outer_node = match outer {
            Some(o) => o,
            None => return,
        };
        if self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.nodes[outer_node].x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.nodes[outer_node].y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                if x < self.min_x {
                    self.min_x = x;
                }
                if y < self.min_y {
                    self.min_y = y;
                }
                if x > self.max_x {
                    self.max_x = x;
                }
                if y > self.max_y {
                    self.max_y = y;
                }
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size are later used to transform coords into
            // integers for z-order calculation
            let mut inv_size = f64::max(self.max_x - self.min_x, self.max_y - self.min_y);
            inv_size = if inv_size != 0.0 { 32767.5 / inv_size } else { 0.0 };
            self.inv_size = inv_size;
        }

        self.earcut_linked(Some(outer_node), 0);
    }

    // create a circular doubly linked list from polygon points in the specified
    // winding order
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> Option<usize> {
        let mut sum = 0.0f64;
        let len = points.len();
        let mut last: Option<usize> = None;

        // calculate original winding order of a polygon ring
        let mut i = 0usize;
        let mut j = if len > 0 { len - 1 } else { 0 };
        while i < len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
            i += 1;
        }

        // link points into circular doubly-linked list in the specified winding
        // order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = Some(self.insert_node(self.vertices + i as u32, points[i][0], points[i][1], last));
            }
        } else {
            let mut i = len;
            while i > 0 {
                last = Some(self.insert_node(
                    self.vertices + (i - 1) as u32,
                    points[i - 1][0],
                    points[i - 1][1],
                    last,
                ));
                i -= 1;
            }
        }

        if let Some(l) = last {
            if self.equals(l, self.nodes[l].next) {
                self.remove_node(l);
                last = Some(self.nodes[l].next);
            }
        }

        self.vertices += len as u32;

        last
    }

    // eliminate colinear or duplicate points
    fn filter_points(&mut self, start: usize, end: Option<usize>) -> usize {
        let mut end = end.unwrap_or(start);

        let mut p = start;
        loop {
            let mut again = false;

            if !self.nodes[p].steiner
                && (self.equals(p, self.nodes[p].next)
                    || self.area(self.nodes[p].prev, p, self.nodes[p].next) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    fn earcut_linked(&mut self, ear: Option<usize>, pass: i32) {
        let mut ear = match ear {
            Some(e) => e,
            None => return,
        };

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any
            // more ears
            if ear == stop {
                // try filtering points and slicing again
                if pass == 0 {
                    let f = self.filter_points(ear, None);
                    self.earcut_linked(Some(f), 1);
                // if this didn't work, try curing all small self-intersections
                // locally
                } else if pass == 1 {
                    let f = self.filter_points(ear, None);
                    let e2 = self.cure_local_intersections(f);
                    self.earcut_linked(Some(e2), 2);
                // as a last resort, try splitting the remaining polygon into two
                } else if pass == 2 {
                    self.split_ears(ear);
                }

                break;
            }
        }
    }

    // check whether a polygon node forms a valid ear with adjacent nodes
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[self.nodes[ear].next].next;

        while p != self.nodes[ear].prev {
            if self.point_in_triangle(
                self.nodes[a].x,
                self.nodes[a].y,
                self.nodes[b].x,
                self.nodes[b].y,
                self.nodes[c].x,
                self.nodes[c].y,
                self.nodes[p].x,
                self.nodes[p].y,
            ) && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let ax = self.nodes[a].x;
        let ay = self.nodes[a].y;
        let bx = self.nodes[b].x;
        let by = self.nodes[b].y;
        let cx = self.nodes[c].x;
        let cy = self.nodes[c].y;

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = f64::min(ax, f64::min(bx, cx));
        let min_ty = f64::min(ay, f64::min(by, cy));
        let max_tx = f64::max(ax, f64::max(bx, cx));
        let max_ty = f64::max(ay, f64::max(by, cy));

        // z-order range for the current triangle bbox;
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;

        while p != NULL && self.nodes[p].z <= max_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && self.point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;

        while p != NULL && self.nodes[p].z >= min_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && self.point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    // go through all polygon nodes and cure small local self-intersections
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut p = start;
        let mut start = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;

            // a self-intersection where edge (a-p) intersects (b-next)
            if !self.equals(a, b)
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                let p_next = self.nodes[p].next;
                self.remove_node(p);
                self.remove_node(p_next);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, None)
    }

    // try splitting polygon into two and triangulate them independently
    fn split_ears(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    a = self.filter_points(a, Some(self.nodes[a].next));
                    c = self.filter_points(c, Some(self.nodes[c].next));

                    // run earcut on each half
                    self.earcut_linked(Some(a), 0);
                    self.earcut_linked(Some(c), 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    // link every hole into the outer loop, producing a single-ring polygon
    // without holes
    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], mut outer_node: usize) -> usize {
        let len = points.len();

        let mut queue: Vec<usize> = Vec::new();
        for i in 1..len {
            let ring = &points[i];
            if !ring.is_empty() {
                let list = self.linked_list(ring, false).unwrap();
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }
        // sort holes by x, ascending (unstable, like std::sort)
        queue.sort_unstable_by(|&a, &b| {
            if self.nodes[a].x < self.nodes[b].x {
                std::cmp::Ordering::Less
            } else if self.nodes[b].x < self.nodes[a].x {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        });

        // process holes from left to right
        for i in 0..queue.len() {
            outer_node = self.eliminate_hole(queue[i], outer_node);
        }

        outer_node
    }

    // find a bridge between vertices that connects hole with an outer ring and
    // link it
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = match self.find_hole_bridge(hole, outer_node) {
            Some(b) => b,
            None => return outer_node,
        };

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let brn = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, Some(brn));

        // Check if input node was removed by the filtering
        let bn = self.nodes[bridge].next;
        self.filter_points(bridge, Some(bn))
    }

    // David Eberly's algorithm for finding a bridge between hole and outer
    // polygon
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> Option<usize> {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m: Option<usize> = None;

        // find a segment intersected by a ray from the hole's leftmost vertex to
        // the left; segment's endpoint with lesser x will be potential connection
        // vertex
        loop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            let n = self.nodes[p].next;
            let nx = self.nodes[n].x;
            let ny = self.nodes[n].y;
            if hy <= py && hy >= ny && ny != py {
                let x = px + (hy - py) * (nx - px) / (ny - py);
                if x <= hx && x > qx {
                    qx = x;
                    if x == hx {
                        if hy == py {
                            return Some(p);
                        }
                        if hy == ny {
                            return Some(n);
                        }
                    }
                    m = Some(if px < nx { p } else { n });
                }
            }
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        let mut m = m?;

        if hx == qx {
            return Some(m); // hole touches outer segment; pick leftmost endpoint
        }

        // look for points inside the triangle of hole vertex, segment
        // intersection and endpoint; if there are no points found, we have a
        // valid connection; otherwise choose the vertex of the minimum angle
        // with the ray as connection vertex

        let stop = m;
        let mut tan_min = f64::INFINITY;

        p = m;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;

        loop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            if hx >= px
                && px >= mx
                && hx != px
                && self.point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan_cur = f64::abs(hy - py) / (hx - px); // tangential

                if self.locally_inside(p, hole)
                    && (tan_cur < tan_min
                        || (tan_cur == tan_min
                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan_cur;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        Some(m)
    }

    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.nodes[m].prev, m, self.nodes[p].prev) < 0.0
            && self.area(self.nodes[p].next, m, self.nodes[m].next) < 0.0
    }

    // interlink polygon nodes in z-order
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let z = self.z_order(self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = z;
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let pz = self.nodes[p].prev_z;
        self.nodes[pz].next_z = NULL;
        self.nodes[p].prev_z = NULL;

        self.sort_linked(p);
    }

    // Simon Tatham's linked list merge sort algorithm
    // http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
    fn sort_linked(&mut self, list: usize) -> usize {
        let mut list = list;
        let mut in_size = 1usize;

        loop {
            let mut p = list;
            list = NULL;
            let mut tail = NULL;
            let mut num_merges = 0;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0usize;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                }

                let mut q_size = in_size;

                // if there are two sorted runs, merge them
                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NULL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NULL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    // z-order of a vertex given coords and size of the data bounding box
    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }

    // find the leftmost node of a polygon ring
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        leftmost
    }

    // check if a point lies within a convex triangle
    #[allow(clippy::too_many_arguments)]
    fn point_in_triangle(
        &self,
        ax: f64,
        ay: f64,
        bx: f64,
        by: f64,
        cx: f64,
        cy: f64,
        px: f64,
        py: f64,
    ) -> bool {
        (cx - px) * (ay - py) >= (ax - px) * (cy - py)
            && (ax - px) * (by - py) >= (bx - px) * (ay - py)
            && (bx - px) * (cy - py) >= (cx - px) * (by - py)
    }

    // check if a diagonal between two polygon nodes is valid (lies in polygon
    // interior)
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        self.nodes[self.nodes[a].next].i != self.nodes[b].i
            && self.nodes[self.nodes[a].prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(self.nodes[a].prev, a, self.nodes[b].prev) != 0.0
                    || self.area(a, self.nodes[b].prev, b) != 0.0)) // does not create opposite-facing sectors
                || (self.equals(a, b)
                    && self.area(self.nodes[a].prev, a, self.nodes[a].next) > 0.0
                    && self.area(self.nodes[b].prev, b, self.nodes[b].next) > 0.0)) // special zero-length case
    }

    // signed area of a triangle
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    // check if two points are equal
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    // check if two segments intersect
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true; // p1, q1 and p2 are collinear and p2 lies on p1q1
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true; // p1, q1 and q2 are collinear and q2 lies on p1q1
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true; // p2, q2 and p1 are collinear and p1 lies on p2q2
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true; // p2, q2 and q1 are collinear and q1 lies on p2q2
        }

        false
    }

    // for collinear points p, q, r, check if point q lies on segment pr
    fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        let (px, py) = (self.nodes[p].x, self.nodes[p].y);
        let (qx, qy) = (self.nodes[q].x, self.nodes[q].y);
        let (rx, ry) = (self.nodes[r].x, self.nodes[r].y);
        qx <= f64::max(px, rx) && qx >= f64::min(px, rx) && qy <= f64::max(py, ry) && qy >= f64::min(py, ry)
    }

    // check if a polygon diagonal intersects any polygon segments
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[self.nodes[p].next].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[self.nodes[p].next].i != self.nodes[b].i
                && self.intersects(p, self.nodes[p].next, a, b)
            {
                return true;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }

        false
    }

    // check if a polygon diagonal is locally inside the polygon
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        if self.area(self.nodes[a].prev, a, self.nodes[a].next) < 0.0 {
            self.area(a, b, self.nodes[a].next) >= 0.0
                && self.area(a, self.nodes[a].prev, b) >= 0.0
        } else {
            self.area(a, b, self.nodes[a].prev) < 0.0
                || self.area(a, self.nodes[a].next, b) < 0.0
        }
    }

    // check if the middle point of a polygon diagonal is inside the polygon
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let x1 = self.nodes[p].x;
            let y1 = self.nodes[p].y;
            let n = self.nodes[p].next;
            let x2 = self.nodes[n].x;
            let y2 = self.nodes[n].y;
            if ((y1 > py) != (y2 > py))
                && y2 != y1
                && (px < (x2 - x1) * (py - y1) / (y2 - y1) + x1)
            {
                inside = !inside;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }

        inside
    }

    // link two polygon vertices with a bridge; if the vertices belong to the same
    // ring, it splits polygon into two; if one belongs to the outer ring and
    // another to a hole, it merges it into a single ring
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.new_node(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.new_node(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    // create a node and optionally link it with previous one (in a circular
    // doubly linked list)
    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<usize>) -> usize {
        let p = self.new_node(i, x, y);

        match last {
            None => {
                self.nodes[p].prev = p;
                self.nodes[p].next = p;
            }
            Some(l) => {
                let ln = self.nodes[l].next;
                self.nodes[p].next = ln;
                self.nodes[p].prev = l;
                self.nodes[ln].prev = p;
                self.nodes[l].next = p;
            }
        }
        p
    }

    fn new_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        let id = self.nodes.len();
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: NULL,
            next: NULL,
            z: 0,
            prev_z: NULL,
            next_z: NULL,
            steiner: false,
        });
        id
    }

    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let prev_z = self.nodes[p].prev_z;
        let next_z = self.nodes[p].next_z;
        if prev_z != NULL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NULL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }
}

fn sign(val: f64) -> i32 {
    (0.0 < val) as i32 - (val < 0.0) as i32
}

